export function evaluateHEarthR06C10OfficialLandformSupportMask(worldX, worldZ) {
  return windowQ5(worldX, 24, 32, 64, 72) *
    windowQ5(worldZ, -200, -192, -164, -156);
}

function orientedCoordinates(worldX, worldZ, operation) {
  const radians = operation.rotationDegrees * Math.PI / 180;
  const cosine = Math.cos(radians);
  const sine = Math.sin(radians);
  const x = worldX - operation.centerX;
  const z = worldZ - operation.centerZ;
  return {
    u: cosine * x + sine * z,
    v: -sine * x + cosine * z
  };
}

function nearestPolylinePoint(worldX, worldZ, polyline) {
  const lengths = [];
  let totalLength = 0;
  for (let index = 0; index < polyline.length - 1; index += 1) {
    const [ax, az] = polyline[index];
    const [bx, bz] = polyline[index + 1];
    const length = Math.hypot(bx - ax, bz - az);
    lengths.push(length);
    totalLength += length;
  }

  let cumulative = 0;
  let nearest = null;
  for (let index = 0; index < polyline.length - 1; index += 1) {
    const [ax, az] = polyline[index];
    const [bx, bz] = polyline[index + 1];
    const vx = bx - ax;
    const vz = bz - az;
    const length = lengths[index];
    const lengthSquared = vx * vx + vz * vz;
    const t = lengthSquared === 0
      ? 0
      : clamp(
        ((worldX - ax) * vx + (worldZ - az) * vz) / lengthSquared,
        0,
        1
      );
    const pointX = ax + t * vx;
    const pointZ = az + t * vz;
    const distance = Math.hypot(worldX - pointX, worldZ - pointZ);
    const progress = totalLength === 0
      ? 0
      : (cumulative + t * length) / totalLength;
    if (nearest === null || distance < nearest.distance) {
      nearest = { distance, progress, totalLength };
    }
    cumulative += length;
  }
  return nearest;
}

function endWindow(progress, totalLength, featherWorldUnits) {
  const normalizedFeather = featherWorldUnits / totalLength;
  return q5(progress / normalizedFeather) *
    q5((1 - progress) / normalizedFeather);
}

export function evaluateHEarthR06C10OfficialLandformOperationDelta(
  worldX,
  worldZ,
  operation
) {
  if (
    operation.operator === 'VALLEY_CORRIDOR' ||
    operation.operator === 'DRAINAGE_CUT'
  ) {
    const nearest = nearestPolylinePoint(worldX, worldZ, operation.polyline);
    return -operation.depth *
      Math.exp(-1.6 * (nearest.distance / operation.halfWidth) ** 2) *
      endWindow(
        nearest.progress,
        nearest.totalLength,
        operation.endFeatherWorldUnits
      );
  }

  const { u, v } = orientedCoordinates(worldX, worldZ, operation);
  switch (operation.operator) {
    case 'ORIENTED_SADDLE':
      return operation.amplitude *
        Math.exp(-1.6 * (
          (u / operation.radiusU) ** 2 +
          (v / operation.radiusV) ** 2
        )) * (
          (v / operation.radiusV) ** 2 -
          (u / operation.radiusU) ** 2
        );
    case 'RIDGE_FACE':
      return operation.height *
        Math.exp(-1.6 * (v / operation.halfWidth) ** 2) *
        longitudinalWindow(u, operation.halfLength, operation.feather);
    case 'LOWER_BASIN': {
      const radial = Math.max(0, 1 - (
        (u / operation.radiusU) ** 2 +
        (v / operation.radiusV) ** 2
      ));
      return -operation.depth * radial ** 2;
    }
    case 'TERRACE_BAND':
      return operation.height *
        longitudinalWindow(u, operation.halfLength, operation.feather) *
        Math.exp(-1.6 * (v / operation.halfWidth) ** 4);
    case 'RIDGE_BREAK':
      return -operation.depth * Math.exp(-1.6 * (
        (u / operation.radiusU) ** 2 +
        (v / operation.radiusV) ** 2
      ));
    case 'FALL_FACE':
      return -operation.drop *
        q5((u + operation.halfLength) / (2 * operation.halfLength)) *
        longitudinalWindow(u, operation.halfLength, operation.feather) *
        Math.exp(-1.6 * (v / operation.halfWidth) ** 2);
    default:
      throw new Error(`UNKNOWN_FROZEN_OPERATOR:${operation.operator}`);
  }
}

export function sampleHEarthR06C10OfficialLandformDelta(worldX, worldZ) {
  let rawDelta = 0;
  for (const operation of H_EARTH_R06_C10_OFFICIAL_LANDFORM_OPERATIONS) {
    rawDelta += evaluateHEarthR06C10OfficialLandformOperationDelta(
      worldX,
      worldZ,
      operation
    );
  }
  const boundedDelta = clamp(rawDelta, -12, 18);
  const supportMask =
    evaluateHEarthR06C10OfficialLandformSupportMask(worldX, worldZ);
  return supportMask * boundedDelta;
}

